class Solution {
  public long calculateScore(String s) {
    int n = s.length();
    int[] head = new int[26], prev = new int[n];
    java.util.Arrays.fill(head, -1);
    long score = 0;
    for (int i = 0; i < n; i++) {
      int c = s.charAt(i) - 'a', m = 25 - c;
      if (head[m] >= 0) {
        score += i - head[m];
        head[m] = prev[head[m]];
      } else {
        prev[i] = head[c];
        head[c] = i;
      }
    }
    return score;
  }
}
